235	/// Classifies a notification into an [`ActivityEventKind`] and whether it is ephemeral.
236	///
237	/// Dispatches on the coarse `event/*` method, then refines on the params' native `type` label.
238	/// Per-token streams (text/thinking deltas, `tool_call_delta`) are the ephemeral arms
239	/// (WS-forward only, never persisted).
240	fn classify_event(method: &str, params: &Value) -> (ActivityEventKind, bool) {
241	    let event_type = params.get(protocol::EVENT_TYPE).and_then(Value::as_str);
242	    match method {
243	        "event/message" => (message_kind(event_type, params), false),
244	        "event/toolCall" => (tool_call_kind(params), false),
245	        "event/toolResult" => (tool_result_kind(params), false),
246	        "event/progress" => progress_kind(event_type, params),
247	        "event/stop" => (stop_kind(params), false),
248	        _ if is_per_token_type(event_type) => {
249	            // A provider-native per-token frame surfacing through an
250	            // unclassified method (e.g. `event/raw` carrying
251	            // `response.function_call_arguments.delta`): same class as the
252	            // `event/progress` delta arms, so same treatment — an ephemeral
253	            // note with the payload dropped. Persisting these wrote the
254	            // finalized turn's content thousands of times over.
255	            let detail = ProgressDetail::Note {
256	                text: event_type.unwrap_or_default().to_owned(),
257	            };
258	            (ActivityEventKind::Progress { detail }, true)
259	        }
260	        _ => (raw_kind(method, params), false),
261	    }
262	}
