264	/// Whether a native event `type` label names a per-token streaming frame.
265	///
266	/// Providers stream deltas under dotted `*.delta` labels (`response.output_text.delta`,
267	/// `response.function_call_arguments.delta`, ...). One frame per token: never
268	/// worth persisting, whatever method it arrived under.
269	fn is_per_token_type(event_type: Option<&str>) -> bool {
270	    event_type.is_some_and(|label| label.contains('.') && label.rsplit('.').next() == Some("delta"))
271	}
