273	/// A required string field, or an empty string when absent — string fields are never fatal.
274	fn string_field(params: &Value, key: &str) -> String {
275	    params
276	        .get(key)
277	        .and_then(Value::as_str)
278	        .unwrap_or_default()
279	        .to_owned()
280	}
