282	/// Builds a [`ActivityEventKind::Message`] from an `event/message` notification.
283	///
284	/// Every Norn `event/message` is agent-produced (assistant text/thinking, or an inter-agent
285	/// message lifecycle), so the neutral role is always [`MessageRole::Assistant`]; an operator
286	/// injection is a distinct intervention, never an `event/message`. The message text is `text`
287	/// (assistant output) or the `content` of a message-lifecycle event when present.
288	fn message_kind(_event_type: Option<&str>, params: &Value) -> ActivityEventKind {
289	    let text = params
290	        .get("text")
291	        .or_else(|| params.get("content"))
292	        .and_then(Value::as_str)
293	        .unwrap_or_default()
294	        .to_owned();
295	    ActivityEventKind::Message {
296	        role: MessageRole::Assistant,
297	        text,
298	    }
299	}
