301	/// Builds a [`ActivityEventKind::ToolCall`] from an `event/toolCall` notification.
302	fn tool_call_kind(params: &Value) -> ActivityEventKind {
303	    ActivityEventKind::ToolCall {
304	        tool: string_field(params, "name"),
305	        call_id: string_field(params, "call_id"),
306	        input: params.get("arguments").cloned().unwrap_or(Value::Null),
307	    }
308	}
309	
310	/// Builds a [`ActivityEventKind::ToolResult`] from an `event/toolResult` notification.
311	fn tool_result_kind(params: &Value) -> ActivityEventKind {
312	    ActivityEventKind::ToolResult {
313	        call_id: string_field(params, "tool_call_id"),
314	        output: params.get("output").cloned().unwrap_or(Value::Null),
315	        is_error: params
316	            .get("is_error")
317	            .and_then(Value::as_bool)
318	            .unwrap_or(false),
319	    }
320	}
