322	/// Builds a progress kind (and its ephemeral flag) from an `event/progress` notification.
323	///
324	/// Token/thinking deltas map to an ephemeral [`ActivityEventKind::Delta`] and tool-argument
325	/// deltas to an ephemeral [`ProgressDetail::Note`]; a usage estimate maps to a persisted
326	/// [`ProgressDetail::UsageEstimate`]; anything else to a persisted [`ProgressDetail::Note`].
327	fn progress_kind(event_type: Option<&str>, params: &Value) -> (ActivityEventKind, bool) {
328	    match event_type {
329	        Some("text_delta" | "thinking_delta") => {
330	            let delta = ActivityEventKind::Delta {
331	                message_id: string_field(params, "item_id"),
332	                text_fragment: string_field(params, "text"),
333	            };
334	            (delta, true)
335	        }
336	        // Tool-argument streaming is per-token, like text/thinking deltas: durable
337	        // persistence would write thousands of rows per large tool call for data
338	        // the finalized tool_call event already carries in full.
339	        Some("tool_call_delta") => {
340	            let detail = ProgressDetail::Note {
341	                text: "tool_call_delta".to_owned(),
342	            };
343	            (ActivityEventKind::Progress { detail }, true)
344	        }
345	        Some("usage_estimate") => {
346	            let detail = ProgressDetail::UsageEstimate {
347	                input_tokens: params.get("input_tokens").and_then(Value::as_u64),
348	                output_tokens: params.get("output_tokens").and_then(Value::as_u64),
349	            };
350	            (ActivityEventKind::Progress { detail }, false)
351	        }
352	        _ => {
353	            let detail = ProgressDetail::Note {
354	                text: event_type.unwrap_or("progress").to_owned(),
355	            };
356	            (ActivityEventKind::Progress { detail }, false)
357	        }
358	    }
359	}
