361	/// Builds a [`ActivityEventKind::Stop`] from an `event/stop` notification's `stop_reason`.
362	fn stop_kind(params: &Value) -> ActivityEventKind {
363	    let reason = match params.get("stop_reason").and_then(Value::as_str) {
364	        Some("end_turn") => StopKind::EndTurn,
365	        Some("tool_use") => StopKind::ToolUse,
366	        Some("max_tokens") => StopKind::LimitReached,
367	        Some(other) => StopKind::Other {
368	            reason: other.to_owned(),
369	        },
370	        None => StopKind::Other {
371	            reason: "unknown".to_owned(),
372	        },
373	    };
374	    ActivityEventKind::Stop { reason }
375	}
