377	/// Builds a [`ActivityEventKind::Raw`] passthrough for an unclassified notification.
378	fn raw_kind(method: &str, params: &Value) -> ActivityEventKind {
379	    ActivityEventKind::Raw {
380	        source: method.to_owned(),
381	        value: params.clone(),
382	    }
383	}
