120	pub(crate) async fn run(
121	    client: &Client,
122	    workflow_id: &str,
123	    run_id: Option<&str>,
124	    config: TailConfig<'_>,
125	) -> Result<Value> {
126	    let workflow_id = parse_workflow_id(workflow_id)?;
127	    let requested_run = run_id.map(parse_run_id).transpose()?;
128	    let http = HttpTailClient::new(&config)?;
129	    let (sources, pending) =
130	        discover_sources(client, &http, &workflow_id, requested_run, &config).await?;
131	    let mut targets = discover_targets(&http, &sources, config.namespace).await?;
132	    mark_superseded(&mut targets);
133	    let heads = backfill_and_print(&http, &targets, config.namespace).await?;
134	    if !config.follow {
135	        return Ok(Value::Null);
136	    }
137	
138	    let mut builder = ClientBuilder::new(config.grpc_endpoint)
139	        .with_stream_endpoint(transcript_socket_url(config.http_endpoint)?)
140	        .with_namespace(config.namespace)
141	        .with_subject(config.subject)
142	        .with_authorized_namespaces([config.namespace]);
143	    if let Some(token) = config.token {
144	        builder = builder.with_auth(ClientAuth::bearer(token));
145	    }
146	    let stream_client = builder
147	        .build()
148	        .await
149	        .context("failed to connect tail workflow-event sockets")?;
150	    live::follow(stream_client, sources, pending, targets, heads).await
151	}
