153	async fn discover_sources(
154	    client: &Client,
155	    http: &HttpTailClient,
156	    workflow_id: &WorkflowId,
157	    requested_run: Option<RunId>,
158	    config: &TailConfig<'_>,
159	) -> Result<(Vec<Source>, Vec<PendingSource>)> {
160	    let description = client
161	        .describe(workflow_id, requested_run.as_ref())
162	        .await
163	        .context("failed to resolve workflow run for tail")?;
164	    let parent_run = requested_run
165	        .or_else(|| latest_run(&description.history))
166	        .ok_or_else(|| anyhow!("workflow history contains no WorkflowStarted run"))?;
167	    let mut sources = vec![Source {
168	        workflow_id: workflow_id.clone(),
169	        run_id: parent_run.clone(),
170	        label: format!("parent {}", short_id(workflow_id)),
171	        is_parent: true,
172	    }];
173	    let children: ChildrenResponse = http
174	        .post(
175	            "/workflows/children",
176	            &ChildrenRequest {
177	                namespace: config.namespace,
178	                workflow_id,
179	                run_id: &parent_run,
180	            },
181	        )
182	        .await?;
183	    let mut pending = Vec::new();
184	    for child in children.children {
185	        let name = child_label(child.display_name.as_deref(), &child.workflow_type);
186	        let label = format!("{name} {}", short_id(&child.workflow_id));
187	        if let Some(child_run) = child.run_id {
188	            sources.push(Source {
189	                label,
190	                workflow_id: child.workflow_id,
191	                run_id: child_run,
192	                is_parent: false,
193	            });
194	        } else {
195	            let action = if config.follow {
196	                "following for its run"
197	            } else {
198	                "no transcript exists in this snapshot"
199	            };
200	            println!("[{label}] child start recorded; run not started yet; {action}");
201	            pending.push(PendingSource {
202	                label,
203	                workflow_id: child.workflow_id,
204	            });
205	        }
206	    }
207	    Ok((sources, pending))
208	}
