243	async fn backfill_and_print(
244	    http: &HttpTailClient,
245	    targets: &[Target],
246	    namespace: &str,
247	) -> Result<Vec<Option<u64>>> {
248	    let mut backfill = Vec::new();
249	    let mut heads = Vec::new();
