253	                "/workflows/transcript",
254	                &json!({
255	                    "namespace": namespace,
256	                    "workflow_id": target.source.workflow_id,
257	                    "run_id": target.source.run_id,
258	                    "activity_id": target.activity_id,
259	                    "attempt": target.attempt,
260	                    "last": MAX_TRANSCRIPT_WINDOW_LIMIT,
261	                }),
262	            )
263	            .await
264	            .with_context(|| format!("failed to backfill {}", prefix(target)))?;
265	        let first_store_seq = transcript.events.first().and_then(|event| event.store_seq);
266	        if let Some(notice) = backfill_notice(
267	            transcript.events.len(),
268	            transcript.head_seq,
269	            first_store_seq,
270	        ) {
271	            println!("{} NOTICE: {notice}", prefix(target));
272	        }
273	        backfill.extend(
274	            transcript
275	                .events
276	                .into_iter()
277	                .map(|event| (event.emitted_at, (prefix(target), event))),
278	        );
279	        heads.push(transcript.head_seq.checked_sub(1));
280	    }
281	    order_backfill(&mut backfill);
282	    for (_, (prefix, event)) in backfill {
283	        println!("{prefix} {}", render_event(&event));
284	    }
285	    for target in targets
286	        .iter()
287	        .filter(|target| target.superseded_by.is_some())
288	    {
289	        println!(
290	            "{} superseded; this stream is no longer working",
291	            prefix(target)
292	        );
293	    }
294	    Ok(heads)
295	}
