303	impl HttpTailClient {
304	    fn new(config: &TailConfig<'_>) -> Result<Self> {
305	        let mut headers = HeaderMap::new();
306	        headers.insert(
307	            "x-aion-subject",
308	            HeaderValue::from_str(config.subject)
309	                .with_context(|| format!("invalid x-aion-subject value {:?}", config.subject))?,
310	        );
311	        headers.insert(
312	            "x-aion-namespaces",
313	            HeaderValue::from_str(config.namespace).with_context(|| {
314	                format!("invalid x-aion-namespaces value {:?}", config.namespace)
315	            })?,
316	        );
317	        if let Some(token) = config.token {
318	            headers.insert(
319	                AUTHORIZATION,
320	                HeaderValue::from_str(&format!("Bearer {token}"))
321	                    .context("invalid authorization bearer token header value")?,
322	            );
323	        }
324	        Ok(Self {
325	            base_url: config.http_endpoint.trim_end_matches('/').to_owned(),
326	            client: reqwest::Client::new(),
327	            headers,
328	        })
329	    }
330	
331	    async fn post<T, B>(&self, path: &str, body: &B) -> Result<T>
332	    where
333	        T: for<'de> Deserialize<'de>,
334	        B: Serialize + ?Sized,
335	    {
336	        self.client
337	            .post(format!("{}{path}", self.base_url))
338	            .headers(self.headers.clone())
339	            .json(body)
340	            .send()
341	            .await
342	            .context("Aion HTTP request failed")?
343	            .error_for_status()
344	            .context("Aion HTTP endpoint refused tail request")?
345	            .json()
346	            .await
347	            .context("Aion HTTP response was invalid")
348	    }
349	}
