355	fn backfill_notice(
356	    event_count: usize,
357	    head_seq: u64,
358	    first_store_seq: Option<u64>,
359	) -> Option<String> {
360	    let first_store_seq = match first_store_seq {
361	        Some(first_store_seq) => first_store_seq,
362	        None if event_count == 0 && head_seq > 0 => {
363	            return Some(format!(
364	                "no retained events; head at durable seq {head_seq}; earlier records were trimmed by retention"
365	            ));
366	        }
367	        None => return None,
368	    };
369	    if first_store_seq <= 1 {
370	        return None;
371	    }
372	    let last_store_seq = head_seq.saturating_sub(1);
373	    Some(format!(
374	        "retained backfill begins at durable seq {first_store_seq}; showing {event_count} events through durable seq {last_store_seq} (earlier records may be unavailable because of retention or the CLI's {MAX_TRANSCRIPT_WINDOW_LIMIT}-event request bound; durable seq {first_store_seq}..{last_store_seq})"
375	    ))
376	}
