385	fn mark_superseded(targets: &mut [Target]) {
386	    let latest: HashMap<_, _> = targets.iter().fold(HashMap::new(), |mut latest, target| {
387	        let key = (
388	            target.source.workflow_id.clone(),
389	            target.activity_id.clone(),
390	        );
391	        latest
392	            .entry(key)
393	            .and_modify(|attempt: &mut u32| *attempt = (*attempt).max(target.attempt))
394	            .or_insert(target.attempt);
395	        latest
396	    });
397	    for target in targets {
398	        let key = (
399	            target.source.workflow_id.clone(),
400	            target.activity_id.clone(),
401	        );
402	        target.superseded_by = latest
403	            .get(&key)
404	            .copied()
405	            .filter(|latest| *latest > target.attempt);
406	    }
407	}
