419	fn render_event(event: &ActivityEvent) -> String {
420	    match &event.kind {
421	        ActivityEventKind::Message { role, text } => format!("{role:?}: {text}"),
422	        ActivityEventKind::Delta { text_fragment, .. } => text_fragment.clone(),
423	        ActivityEventKind::ToolCall { tool, input, .. } => format!("tool {tool} {input}"),
424	        ActivityEventKind::ToolResult {
425	            output, is_error, ..
426	        } => format!(
427	            "tool result{} {output}",
428	            if *is_error { " ERROR" } else { "" }
429	        ),
430	        ActivityEventKind::Progress { detail } => format!("progress {detail:?}"),
431	        ActivityEventKind::Stop { reason } => format!("stopped {reason:?}"),
432	        ActivityEventKind::Raw { source, value } => format!("{source}: {value}"),
433	    }
434	}
