36	/// A live Norn run for one activity attempt.
37	///
38	/// Generic over the child's read/write halves so tests can drive it over an in-memory duplex; in
39	/// production the halves are the child process's stdout/stdin.
40	pub struct NornSession<R, W> {
41	    connection: Arc<JsonRpcConnection<R, W>>,
42	    capabilities: InterventionCapabilities,
43	    events: Option<mpsc::UnboundedReceiver<ActivityEvent>>,
44	    waiters: Waiters,
45	    run_id: JsonRpcId,
46	    run_result: Option<oneshot::Receiver<JsonRpcResponse>>,
47	    pump: Option<tokio::task::JoinHandle<()>>,
48	    /// The spawned child, reaped when the session is dropped. `None` for the in-memory test path.
49	    child: Option<tokio::process::Child>,
