52	impl<R, W> NornSession<R, W>
53	where
54	    R: AsyncRead + Unpin + Send + 'static,
55	    W: AsyncWrite + Unpin + Send + 'static,
56	{
57	    /// Builds a session over an already-handshaked connection and starts the reader pump.
58	    ///
59	    /// `run_id` is the id of the outstanding `run/execute` request whose Response is the result.
60	    /// `identity` stamps the run key onto every translated event. The pump is started here so
61	    /// events stream from the moment the session exists.
62	    pub(crate) fn start(
63	        connection: Arc<JsonRpcConnection<R, W>>,
64	        capabilities: InterventionCapabilities,
65	        run_id: JsonRpcId,
66	        identity: EventIdentity,
67	        child: Option<tokio::process::Child>,
68	    ) -> Self {
69	        let (event_tx, event_rx) = mpsc::unbounded_channel();
70	        let (result_tx, result_rx) = oneshot::channel();
71	
72	        // Register the run/execute waiter into the map BEFORE the pump can observe its Response, by
73	        // building the map with the entry already present — no lock, no `.await` in this sync ctor.
74	        let mut initial = HashMap::new();
75	        initial.insert(run_id.clone(), result_tx);
76	        let waiters: Waiters = Arc::new(Mutex::new(initial));
77	
78	        let pump = tokio::spawn(pump_loop(
79	            Arc::clone(&connection),
80	            Arc::clone(&waiters),
81	            event_tx,
82	            identity,
83	        ));
84	
85	        Self {
86	            connection,
87	            capabilities,
88	            events: Some(event_rx),
89	            waiters,
90	            run_id,
91	            run_result: Some(result_rx),
92	            pump: Some(pump),
93	            child,
94	        }
95	    }
96	}
