98	/// The reader pump: demultiplexes every inbound frame until end-of-stream.
99	///
100	/// Notifications become events; Responses are routed to their id's waiter; child-initiated
101	/// Requests are traced and dropped (out of NOI-4 scope). On a transport error or EOF the loop
102	/// ends, the event channel closes (ending the events stream), and any un-answered waiter observes
103	/// a dropped sender (a `RecvError` its awaiter maps to a transport error).
104	async fn pump_loop<R, W>(
105	    connection: Arc<JsonRpcConnection<R, W>>,
106	    waiters: Waiters,
107	    event_tx: mpsc::UnboundedSender<ActivityEvent>,
108	    identity: EventIdentity,
109	) where
110	    R: AsyncRead + Unpin + Send,
111	    W: AsyncWrite + Unpin + Send,
112	{
113	    let mut worker_seq: u64 = 0;
114	    loop {
115	        match connection.recv().await {
116	            Ok(Some(IncomingMessage::Notification(note))) => {
117	                let params = note.params.unwrap_or(serde_json::Value::Null);
118	                let event =
119	                    translate::notification_to_event(&identity, worker_seq, &note.method, &params);
120	                worker_seq = worker_seq.saturating_add(1);
121	                // A send failure means the consumer dropped the events stream; keep pumping so the
122	                // result and acks still route, just stop forwarding events. Not an error.
123	                let _ = event_tx.send(event);
124	            }
125	            Ok(Some(IncomingMessage::Response(response))) => {
126	                if let Some(sender) = waiters.lock().await.remove(&response.id) {
127	                    // A dropped receiver (the waiter gave up) is not an error worth surfacing.
128	                    let _ = sender.send(response);
129	                }
130	            }
131	            Ok(Some(IncomingMessage::Request(request))) => {
132	                tracing::debug!(
133	                    method = %request.method,
134	                    "norn adapter: ignoring child-initiated request (out of NOI-4 scope)",
135	                );
136	            }
137	            Ok(None) => return,
138	            Err(error) => {
139	                tracing::debug!(%error, "norn adapter: reader pump ended on transport error");
140	                return;
141	            }
142	        }
143	    }
144	}
