156	    fn events(&mut self) -> BoxStream<'static, ActivityEvent> {
157	        // The stream is taken once; a second call yields an empty stream rather than panicking.
158	        match self.events.take() {
159	            Some(receiver) => Box::pin(futures::stream::unfold(
160	                receiver,
161	                |mut receiver| async move { receiver.recv().await.map(|event| (event, receiver)) },
162	            )),
163	            None => Box::pin(futures::stream::empty()),
164	        }
165	    }
