167	    async fn intervene(&self, cmd: InterventionCommand) -> Result<(), HarnessError> {
168	        // Capability-gate FIRST: an unadvertised primitive is rejected before any request is sent,
169	        // and the three unsupported primitives never even build a Norn request.
170	        if !self.capabilities.supports(&cmd.kind) {
171	            return Err(HarnessError::capability_not_supported(format!(
172	                "{:?}",
173	                cmd.kind.primitive()
174	            )));
175	        }
176	        let request = translate::intervention_to_request(&cmd.kind)?;
177	
178	        let id = self.connection.next_request_id();
179	        let (ack_tx, ack_rx) = oneshot::channel();
180	        self.waiters.lock().await.insert(id.clone(), ack_tx);
181	
182	        let frame = JsonRpcRequest::new(id.clone(), request.method, Some(request.params));
183	        if let Err(error) = self.connection.send_request(&frame).await {
184	            self.waiters.lock().await.remove(&id);
185	            return Err(error);
186	        }
187	
188	        let response = ack_rx.await.map_err(|_recv| {
189	            HarnessError::transport("intervene ack channel closed before reply")
190	        })?;
191	        response_into_ack(response)
192	    }
193	
194	    async fn wait_result(mut self) -> Result<Payload, HarnessError> {
195	        let receiver = self
196	            .run_result
197	            .take()
198	            .ok_or_else(|| HarnessError::protocol("run result already awaited"))?;
199	        let response = receiver.await.map_err(|_recv| {
200	            HarnessError::transport("run/execute response channel closed before reply")
201	        })?;
202	        debug_assert_eq!(
203	            response.id, self.run_id,
204	            "pump routed the run/execute response"
205	        );
206	        response_into_payload(response)
207	    }
208	}
