210	/// Interprets an `intervene/*` Response as an ack: success is `Ok(())`, an error object surfaces.
211	fn response_into_ack(response: JsonRpcResponse) -> Result<(), HarnessError> {
212	    if let Some(error) = response.error {
213	        return Err(HarnessError::harness(format!(
214	            "intervene rejected (code {}): {}",
215	            error.code, error.message
216	        )));
217	    }
